/** Busca sonidos por texto en id, categoría, tags o usos. */
export const sfxSearch = (q: string): SfxMeta[] => {
  const needle = q.toLowerCase();
  return Object.values(SFX_INDEX).filter((s) =>
    [s.id, s.cat, ...s.tags, ...s.use].join(' ').toLowerCase().includes(needle),
  );
};

/** Sonidos de una categoría. */
export const sfxByCategory = (cat: string): SfxMeta[] =>
  Object.values(SFX_INDEX).filter((s) => s.cat === cat);
